  assert.equal(digest(path.join(assets,'paired.mjs')), selection.implementation.driverSha256);
  assert.equal(digest(path.join(assets,'native_fixture.mjs')), selection.implementation.fixtureDriverSha256);
  assert.equal(digest(path.join(assets,'query_server.py')), selection.implementation.serverSha256);
}
const configs = selection ? [selection.config] : declaration.configs;
const binarySha256 = digest(path.join(assets,'paired-native'));
assert.equal(binarySha256,'485c241c1e05278bbfb3cd6e13b53e6d47849cd7a91665211828c0b193f7ba54');
const fixture = seed();
const startup = performance.now();
const python = spawn('/Users/liuyuyu/.cache/uv/environments-v2/runner-62575ba291bdd0dc/bin/python',
  [path.join(assets,'query_server.py')], {cwd:assets, env:{...process.env,HF_HUB_OFFLINE:'1',TRANSFORMERS_OFFLINE:'1'}, stdio:['pipe','pipe','inherit']});
const lines = createInterface({input:python.stdout})[Symbol.asyncIterator]();
const readyLine = await lines.next();
assert.equal(readyLine.done,false);
const ready = JSON.parse(readyLine.value);
assert.equal(ready.ready,true);
const startupWallMs = performance.now()-startup;
