const expectations = load(path.join(fixtures,`${split}.expected.json`));
const queries = load(path.join(fixtures,`${split}.queries.json`)).map((query)=>({...query,expected:expectations[query.id]}));
assert.deepEqual(Object.keys(expectations).sort(),queries.map((query)=>query.id).sort());
const rows = [];
for (const query of queries) {
  const started = performance.now();
  const terms = protocol.queryTerms(query.prompt);
  const argv = ['recall',terms.join(' '),'--match','any','--limit','3','--max-chars','6000',
    '--targets-json',JSON.stringify(fixture.targets[query.context]),...(query.selector??[])];
  const lexical = fixture.cli(argv);
  const lexicalObserved = observe(fixture,query,lexical.receipt);
  const lexicalThroughRenderMs = performance.now()-started;
  const semanticStarted = performance.now();
  python.stdin.write(`${JSON.stringify({text:query.prompt})}\n`);
  const response = await lines.next();
  assert.equal(response.done,false);
  const semantic = JSON.parse(response.value);
  assert.equal(semantic.ranking.length,22);
  const semanticIpcMs = performance.now()-semanticStarted;
  const commonMs = performance.now()-started;
  const hybrid = configs.map((config)=>{
    const fusionStarted = performance.now();
    const result = fuse(fixture,query,{config,lexical,semantic});
    const fusionRenderMs = performance.now()-fusionStarted;
    return {config, ...result, fusionRenderMs, wallMs:commonMs+fusionRenderMs};
  });
  rows.push({...query, split, argv:[...argv,'--json'].map((arg)=>arg.replaceAll(fixture.sandbox,'<sandbox>')),
    lexical:{...lexicalObserved,wallMs:lexical.wallMs,throughRenderMs:lexicalThroughRenderMs,peakRssBytes:lexical.peakRssBytes},
    semantic:{...semantic,ipcMs:semanticIpcMs}, hybrid });
