  const fixed = paired.filter((row)=>!row.lexical.score.success&&row.hybrid.score.success).map((row)=>row.id);
  const broken = paired.filter((row)=>row.lexical.score.success&&!row.hybrid.score.success).map((row)=>row.id);
  const fixedPositives = paired.filter((row)=>row.expected.expectedIDs.length&&!row.lexical.score.success&&row.hybrid.score.success).map((row)=>row.id);
  const brokenPositives = paired.filter((row)=>row.expected.expectedIDs.length&&row.lexical.score.success&&!row.hybrid.score.success).map((row)=>row.id);
  const extraNegativeNoise = paired.filter((row)=>!row.expected.expectedIDs.length &&
    (Number(row.hybrid.score.negativeNoise)>Number(row.lexical.score.negativeNoise)||row.hybrid.returned.length>row.lexical.returned.length)).map((row)=>row.id);
