  return {config, summary:scorer.summarize(paired.map((row)=>row.hybrid)), fixed,broken,fixedPositives,brokenPositives,extraNegativeNoise,safety,
    qualityPass:fixedPositives.length>0&&brokenPositives.length===0&&extraNegativeNoise.length===0&&Object.values(safety).every((value)=>value.length===0)};
