  freezeSha256:selection?digest(freezePath):null,fixtureFreeze:frozen,binarySha256,packageVersion:rows[0].lexical.receipt.package_version,
  implementation:{driverSha256:digest(path.join(assets,'paired.mjs')),fixtureDriverSha256:digest(path.join(assets,'native_fixture.mjs')),serverSha256:digest(path.join(assets,'query_server.py')),
    protocolSha256:digest(path.join(root,'plugin/protocol.js')),referencesSha256:digest(path.join(root,'plugin/references.js')),querySha256:digest(path.join(root,'plugin/query.js')),scoringSha256:digest(path.join(fixtures,'scoring.mjs'))},
  model:{revision:'2c4055b12046f11709e9df2c122e59ffbdc2f900',sha256:digest(path.join(assets,'model_quantized.onnx')),vectorsSha256:digest(path.join(assets,'vectors.json')),canonicalFullBodiesVerified:22},
  resources:{platform:process.platform,arch:process.arch,startupWallMs,encoderReady:ready,
    pythonPeakRssBytes:Math.max(ready.peakRssBytes,...rows.map((row)=>row.semantic.peakRssBytes)),
    nodePeakRssBytes:process.resourceUsage().maxRSS*1024,nativePeakRssBytes:Math.max(...rows.map((row)=>row.lexical.peakRssBytes)),
    assetBytes:135392208,onnxRuntimeInstalledBytes:65278097,totalRuntimeInstalledBytes:147070538,
    databaseBytes:{afterSeed:fixture.seedBytes,afterEvaluation:statSync(fixture.db).size}},
