import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, mkdtempSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';

export const root = '/Users/liuyuyu/program/github/LYY/memocap-memory-recall-v0.6.0';
export const assets = '/var/folders/x_/n5qr2_211jg2j9_7q_gdxw940000gn/T/opencode/memocap-semantic.XEF9ebX0';
export const fixtures = path.join(root, 'tests/retrieval-evaluation');
export const digest = (file) => createHash('sha256').update(readFileSync(file)).digest('hex');
export const load = (file) => JSON.parse(readFileSync(file, 'utf8'));
export const protocol = await import(path.join(root, 'plugin/protocol.js'));
export const scorer = await import(path.join(fixtures, 'scoring.mjs'));
export const frozen = load(path.join(fixtures, 'freeze.json'));
for (const [name, hash] of Object.entries(frozen.sha256)) assert.equal(digest(path.join(fixtures, name)), hash);
export const records = load(path.join(fixtures, 'corpus.json')).records.map((record) => ({ ...record,
  content: record.content + (record.repeat ? record.repeat.text.repeat(record.repeat.count) : '') + (record.suffix ?? '') }));
const vectors = load(path.join(assets, 'vectors.json'));
assert.equal(vectors.length, records.length);
for (const record of records) {
  const vector = vectors.find((row) => row.id === record.id);
  assert.equal(vector.body_sha256, createHash('sha256').update(record.content).digest('hex'));
  assert.equal(vector.body_utf8_bytes, Buffer.byteLength(record.content));
  assert.equal(vector.vector.length, 384);
}

export function seed() {
  const sandbox = mkdtempSync(path.join(assets, 'paired-sandbox-'));
  const env = Object.fromEntries(Object.entries(process.env).filter(([key]) =>
    !key.startsWith('MEMOCAP_') && !key.startsWith('GIT_') && !['HOME','XDG_CONFIG_HOME','XDG_DATA_HOME','XDG_CACHE_HOME'].includes(key)));
  Object.assign(env, { HOME:sandbox, MEMOCAP_HOME:sandbox, MEMOCAP_DB:path.join(sandbox,'fixture.db'),
    MEMOCAP_DATA_DIR:path.join(sandbox,'data'), XDG_CONFIG_HOME:path.join(sandbox,'config'),
    XDG_DATA_HOME:path.join(sandbox,'data'), XDG_CACHE_HOME:path.join(sandbox,'cache') });
  for (const name of ['A','B','config','data','cache']) mkdirSync(path.join(sandbox,name));
  const binary = path.join(assets, 'paired-native');
  const cli = (argv) => {
    const start = performance.now();
    const result = spawnSync('/usr/bin/time', ['-l', binary, ...argv, '--json'],
      { cwd:sandbox, env, encoding:'utf8', timeout:30000, maxBuffer:4*1024*1024 });
    const wallMs = performance.now() - start;
    if (result.error) throw result.error;
    assert.equal(result.status, 0, `${result.stderr}\n${result.stdout}`);
    const receipt = JSON.parse(result.stdout);
    assert.equal(receipt.backend, 'local');
    assert.ok(['ok','empty','inserted'].includes(receipt.status));
    const rss = result.stderr.match(/(\d+)\s+maximum resident set size/u);
    assert.ok(rss);
    return { receipt, wallMs, peakRssBytes:Number(rss[1]) };
  };
  const targets = Object.fromEntries(['A','B'].map((name) => [name, cli(['scope','resolve','--repo',path.join(sandbox,name)]).receipt.targets]));
  cli(['scope','domain','create','synthetic-ops','--repo',path.join(sandbox,'A')]);
  for (const name of ['A','B']) cli(['scope','domain','attach','synthetic-ops','--repo',path.join(sandbox,name)]);
  const ids = new Map();
  const entries = new Map();
  for (const record of records) {
    const selector = record.origin === 'universal' ? ['--universal'] : record.origin === 'domain' ? ['--domain','synthetic-ops'] : [];
    const argv = ['remember',record.content,'--force','--repo',path.join(sandbox,record.origin === 'B' ? 'B':'A'),...selector];
    if (record.topic) argv.push('--topic',record.topic);
    const { receipt } = cli(argv);
    ids.set(receipt.returned_ids[0],record.id);
    entries.set(record.id, receipt.results[0]);
  }
  for (const placement of new Set([...entries.values()].map((entry) => entry.memory.placement))) {
    const listed = cli(['list','--placement',placement,'--limit','100','--repo',path.join(sandbox,'A')]).receipt;
    for (const entry of listed.results) assert.equal(entry.memory.content, records.find((record) => record.id === ids.get(entry.memory.id)).content);
  }
  return { sandbox, cli, ids, entries, targets, seedBytes:statSync(env.MEMOCAP_DB).size, db:env.MEMOCAP_DB,
    logical:(id) => { assert.ok(ids.has(id)); return ids.get(id); } };
}

export function observe(fixture, query, receipt) {
  protocol.validateMemories(receipt);
  const block = protocol.referenceBlock(receipt, {});
  assert.ok(block.text.length <= 6000);
  const references = JSON.parse(block.text.slice(block.text.indexOf('\n')+1)).references;
  const logical = fixture.logical;
  const complete = references.filter((reference) => reference.content === records.find((record) => record.id === logical(reference.id)).content).map((reference) => logical(reference.id));
  const observed = { returned:receipt.returned_ids.map(logical), candidates:receipt.matched_ids.map(logical), complete };
  const selectorLeakage = query.selector ? observed.returned.filter((id) => records.find((record) => record.id === id).origin !== 'universal') : [];
  const partialAsFull = references.filter((reference) => reference.completeness === 'full' && !complete.includes(logical(reference.id))).map((reference) => logical(reference.id));
  for (const reference of references) {
    const entry = fixture.entries.get(logical(reference.id));
    assert.equal(reference.content_hash, createHash('sha256').update(entry.memory.content).digest('hex'));
    assert.deepEqual(reference.read, {tool:'memocap_read', arguments:{id:entry.memory.id, placement:entry.memory.placement, content_hash:reference.content_hash}});
  }
  const score = scorer.scoreCase(query.expected, observed, records);
  return { ...observed, selectorLeakage, partialAsFull, score:{...score,success:score.success && selectorLeakage.length===0 && partialAsFull.length===0},
    referenceChars:block.text.length, injected:references.map((reference)=>logical(reference.id)),
    partial:references.filter((reference)=>reference.completeness==='partial').map((reference)=>logical(reference.id)),
    truncated:receipt.truncated, rendered:block.text.replaceAll(fixture.sandbox,'<sandbox>'), receipt };
}

export function fuse(fixture, query, pair) {
  const { config, lexical, semantic } = pair;
  const rank = new Map(lexical.receipt.matched_ids.map((id,index)=>[fixture.logical(id),index+1]));
  const typeIndex = (query.selector??[]).indexOf('--type');
  const kind = typeIndex>=0 ? query.selector[typeIndex+1].trim() : '';
  const allowed = semantic.ranking.filter((item) => {
    const entry = fixture.entries.get(item.id);
    return lexical.receipt.searched_placements.includes(entry.memory.placement) && (!kind || entry.memory.kind === kind);
  });
  const semanticRank = new Map(allowed.map((item,index)=>[item.id,index+1]));
  const admitted = allowed.filter((item)=>item.cosine>=config.threshold);
  const union = [...new Set([...rank.keys(),...admitted.map((item)=>item.id)])];
  const fused = union.map((id)=>({id, lexicalRank:rank.get(id)??null, semanticRank:semanticRank.get(id)??null,
    cosine:semantic.ranking.find((item)=>item.id===id).cosine,
    fusion:(rank.has(id)?1/(config.k+rank.get(id)):0)+(admitted.some((item)=>item.id===id)?config.semanticWeight/(config.k+semanticRank.get(id)):0)}))
    .sort((left,right)=>right.fusion-left.fusion || (left.lexicalRank??Infinity)-(right.lexicalRank??Infinity) || left.id.localeCompare(right.id));
  const selected = [];
  let remaining = 6000;
  for (const item of fused.slice(0,3)) {
    const entry = fixture.entries.get(item.id);
    const chars = Array.from(entry.memory.content).length;
    if (chars>remaining) break;
    remaining -= chars;
    selected.push({...entry, source_order:0, visibility:'visible', applicable_repositories:[], applicability:'unknown', shadowed_by:null});
  }
  const receipt = {...lexical.receipt, results:selected, returned_ids:selected.map((entry)=>entry.memory.id),
    matched_ids:fused.map((item)=>fixture.entries.get(item.id).memory.id), truncated:selected.length<fused.length,
    status:selected.length ? 'ok':'empty'};
  return {...observe(fixture, query, receipt), fused, authorizedSemantic:allowed};
}

