import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, statSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { assets, fixtures, digest, load, protocol, scorer, records } from './native_fixture.mjs';

const prefix = 'semantic-paired-20261111-r1';
const tuning = load(path.join(fixtures,`${prefix}-tuning.json`));
const holdout = load(path.join(fixtures,`${prefix}-holdout.json`));
const freezePath = path.join(fixtures,`${prefix}-freeze.json`);
const freeze = load(freezePath);
assert.equal(holdout.freezeSha256,digest(freezePath));
assert.equal(freeze.tuningSha256,digest(path.join(fixtures,`${prefix}-tuning.json`)));
assert.ok(load(path.join(assets,'holdout-started.json')).at>freeze.frozenAt);
assert.equal(digest(path.join(assets,'paired.mjs')),freeze.implementation.driverSha256);
assert.equal(digest(path.join(assets,'native_fixture.mjs')),freeze.implementation.fixtureDriverSha256);
assert.equal(digest(path.join(assets,'query_server.py')),freeze.implementation.serverSha256);
const retainedHashes = freeze.priorReports.map(({name,sha256})=>({name,sha256,unchanged:digest(path.join(fixtures,name))===sha256}));
assert.ok(retainedHashes.every((item)=>item.unchanged));
const groupBy = (cases,key) => Object.fromEntries([...new Set(cases.map(key))].map((group)=>{
  const rows = cases.filter((row)=>key(row)===group);
  return [group,{cases:rows.map((row)=>row.id),lexical:scorer.summarize(rows.map((row)=>row.lexical)),
    hybrid:scorer.summarize(rows.map((row)=>row.hybrid.find((item)=>item.config.id===freeze.config.id)))}];
}));
const groups = (report)=>({byFamily:groupBy(report.cases,(row)=>row.family),
  byExpectedOrigin:groupBy(report.cases,(row)=>[...new Set(row.expected.expectedIDs.map((id)=>records.find((record)=>record.id===id).origin))].sort().join('+')||'no-answer')});
const fullReadDiagnostics = [];
for (const caseID of ['h-tail','h-unicode']) {
  const row = holdout.cases.find((item)=>item.id===caseID);
  const target = row.lexical.receipt.targets[0];
  const sandbox = path.dirname(target.canonical_path);
  const env = Object.fromEntries(Object.entries(process.env).filter(([key])=>!key.startsWith('MEMOCAP_')&&!key.startsWith('GIT_')&&!['HOME','XDG_CONFIG_HOME','XDG_DATA_HOME','XDG_CACHE_HOME'].includes(key)));
  Object.assign(env,{HOME:sandbox,MEMOCAP_HOME:sandbox,MEMOCAP_DB:path.join(sandbox,'fixture.db'),MEMOCAP_DATA_DIR:path.join(sandbox,'data'),
    XDG_CONFIG_HOME:path.join(sandbox,'config'),XDG_DATA_HOME:path.join(sandbox,'data'),XDG_CACHE_HOME:path.join(sandbox,'cache')});
  const requested = {id:row.lexical.receipt.matched_ids[0],placement:target.repository_id};
  const read = (request)=>{
    const started = performance.now();
    const result = spawnSync(path.join(assets,'paired-native'),['read',String(request.id),'--placement',request.placement,'--repo',target.canonical_path,'--json'],
      {cwd:sandbox,env,encoding:'utf8',timeout:3000,maxBuffer:4*1024*1024});
    assert.equal(result.status,0,result.stderr);
    return {receipt:protocol.validateRead(JSON.parse(result.stdout),request),wallMs:performance.now()-started};
  };
  const initial = read(requested);
  const record = records.find((item)=>item.id===row.expected.expectedIDs[0]);
  assert.equal(initial.receipt.results[0].memory.content,record.content);
  const rendered = protocol.referenceBlock(initial.receipt,{});
  const reference = JSON.parse(rendered.text.slice(rendered.text.indexOf('\n')+1)).references[0];
  assert.equal(reference.completeness,'partial');
  assert.ok(reference.content.length<record.content.length);
  assert.equal(reference.content_hash,createHash('sha256').update(record.content).digest('hex'));
  assert.equal(reference.read.tool,'memocap_read');
  const followed = read(reference.read.arguments);
  assert.equal(followed.receipt.record_changed,false);
  assert.equal(followed.receipt.results[0].memory.content,record.content);
